import React, { useState } from 'react';
import { ButtonGroup, Button, Tooltip } from '@mui/material';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import EuroIcon from '@mui/icons-material/Euro';
import CurrencyPoundIcon from '@mui/icons-material/CurrencyPound';

const CurrencyButtonGroup = () => {
    const [selectedCurrency, setSelectedCurrency] = useState('dollar'); // State to track selected currency

    return (
        <ButtonGroup
            variant="contained"
            color="secondary"
            fullWidth
            sx={{
                borderRadius: '8px', // Rounded corners
                boxShadow: '0px 4px 6px rgba(0, 0, 0, 0.1)', // Subtle shadow
                overflow: 'hidden', // Ensure rounded corners are applied
                '& .MuiButton-root': {
                    flex: 1, // Equal width for all buttons
                    padding: '8px', // Padding for better spacing
                    transition: 'background-color 0.3s ease, transform 0.2s ease', // Smooth transitions
                    '&:hover': {
                        backgroundColor: 'primary.dark', // Darker color on hover
                        transform: 'scale(1.05)' // Slight scale-up effect
                    },
                    '&.Mui-selected': {
                        backgroundColor: 'primary.main', // Highlight selected button
                        color: '#fff' // White text for contrast
                    }
                }
            }}
        >
            {/* Dollar Button */}
            <Tooltip title="Select Dollar" arrow>
                <Button onClick={() => setSelectedCurrency('dollar')} className={selectedCurrency === 'dollar' ? 'Mui-selected' : ''}>
                    <AttachMoneyIcon fontSize="medium" />
                </Button>
            </Tooltip>

            {/* Euro Button */}
            <Tooltip title="Select Euro" arrow>
                <Button onClick={() => setSelectedCurrency('euro')} className={selectedCurrency === 'euro' ? 'Mui-selected' : ''}>
                    <EuroIcon fontSize="medium" />
                </Button>
            </Tooltip>

            {/* Pound Button */}
            <Tooltip title="Select Pound" arrow>
                <Button onClick={() => setSelectedCurrency('pound')} className={selectedCurrency === 'pound' ? 'Mui-selected' : ''}>
                    <CurrencyPoundIcon fontSize="medium" />
                </Button>
            </Tooltip>
        </ButtonGroup>
    );
};

export default CurrencyButtonGroup;
